insert into public.markets (slug, name, state_code, time_zone, center, boundary, status)
select v.slug, v.name, v.state_code, v.time_zone,
       extensions.st_setsrid(extensions.st_makepoint(v.lng, v.lat), 4326)::extensions.geography,
       (select extensions.st_multi(extensions.st_makevalid(extensions.st_union(c.geom)))::extensions.geography from seed_counties c where c.market_slug = v.slug),
       v.status::public.market_status
from (values
  ('san-antonio', 'San Antonio', 'TX', 'America/Chicago', 29.4241::double precision, -98.4936::double precision, 'test'),
  ('las-vegas', 'Las Vegas', 'NV', 'America/Los_Angeles', 36.1699::double precision, -115.1398::double precision, 'test'),
  ('houston', 'Houston', 'TX', 'America/Chicago', 29.7604::double precision, -95.3698::double precision, 'test'),
  ('phoenix', 'Phoenix', 'AZ', 'America/Phoenix', 33.4484::double precision, -112.074::double precision, 'paused'),
  ('orlando', 'Orlando', 'FL', 'America/New_York', 28.5384::double precision, -81.3789::double precision, 'paused')
) as v(slug, name, state_code, time_zone, lat, lng, status)
on conflict (slug) do nothing;

insert into public.market_services (market_id, service_id, enabled, price_min_cents, price_max_cents, price_note, platform_fee_cents, effective_from)
select m.id, s.id, p.enabled, p.price_min_cents, p.price_max_cents, p.price_note, p.platform_fee_cents, '2026-11-13T00:00:00Z'::timestamptz
from public.markets m
cross join (values
  ('flat-tire', true, 5000::integer, 16000::integer, null, 2250::integer),
  ('wont-start', true, 5000::integer, 15000::integer, null, 2250::integer),
  ('locked-out', true, 5000::integer, 17000::integer, null, 2750::integer),
  ('out-of-gas', true, 5000::integer, 19000::integer, 'plus_fuel', 2250::integer),
  ('tow', true, 8200::integer, 13000::integer, 'plus_per_mile', 4250::integer),
  ('winch-out', false, null::integer, null::integer, null, null::integer)
) as p(service_slug, enabled, price_min_cents, price_max_cents, price_note, platform_fee_cents)
join public.services s on s.slug = p.service_slug::extensions.citext
where m.slug in ('san-antonio', 'las-vegas', 'houston', 'phoenix', 'orlando')
on conflict (market_id, service_id, effective_from) do nothing;
